const response = pm.response.json();

// ── Tests ────────────────────────────────────────────────
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response contains auth_token", function () {
    pm.expect(response).to.have.property("auth_token");
    pm.expect(response.auth_token).to.be.a("string").and.not.empty;
});

// ── Token extraction ─────────────────────────────────────
if (pm.response.code === 200) {
    const token = response.auth_token || response.token;
    if (token) {
        pm.environment.set("token", token);
        console.log("✅ Token saved to {{token}}:", token);
    } else {
        console.warn("⚠️ Login succeeded but no token found in response:", JSON.stringify(response));
    }
} else {
    console.warn("⚠️ Login failed — status:", pm.response.code, JSON.stringify(response));
}
